using YunXiaoJob.Application.DTOs.Responses;
using YunXiaoJob.Application.Interfaces;
using YunXiaoJob.Application.Interfaces.Repositories;
namespace YunXiaoJob.Application.UseCases.Notifications;
public class GetMyNotificationsUseCase { private readonly INotificationRepository _notifications; public GetMyNotificationsUseCase(INotificationRepository notifications) => _notifications = notifications; public async Task<IReadOnlyList<NotificationResponse>> ExecuteAsync(Guid currentUserId, CancellationToken cancellationToken = default) => (await _notifications.GetByUserIdAsync(currentUserId, cancellationToken)).Select(x => new NotificationResponse(x.Id, x.Title, x.Content, x.Type, x.TargetUrl, x.IsRead, x.CreatedAtUtc)).ToList(); }
public class MarkNotificationReadUseCase { private readonly INotificationRepository _notifications; private readonly IUnitOfWork _unitOfWork; public MarkNotificationReadUseCase(INotificationRepository notifications, IUnitOfWork unitOfWork) { _notifications = notifications; _unitOfWork = unitOfWork; } public async Task<NotificationResponse> ExecuteAsync(Guid notificationId, Guid currentUserId, CancellationToken cancellationToken = default) { var item = await _notifications.GetByIdAsync(notificationId, cancellationToken) ?? throw new KeyNotFoundException(); if (item.UserId != currentUserId) throw new UnauthorizedAccessException(); item.IsRead = true; item.UpdatedAtUtc = DateTime.UtcNow; await _unitOfWork.SaveChangesAsync(cancellationToken); return new NotificationResponse(item.Id, item.Title, item.Content, item.Type, item.TargetUrl, item.IsRead, item.CreatedAtUtc); } }
